import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const LOAN_TYPES = ['BORROWING', 'LENDING'];
const DATE_FORMAT = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function pageOf(q: Record<string, unknown>): { page: number; size: number } {
  const rawPage = text(q['page']);
  const rawSize = text(q['size']);
  const page = rawPage === '' ? 0 : Number(rawPage);
  let size = rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
  if (!Number.isInteger(page) || page < 0) {
    throw invalid('page는 0 이상의 정수여야 합니다.');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw invalid('size는 1 이상의 정수여야 합니다.');
  }
  if (size > MAX_SIZE) {
    size = MAX_SIZE;
  }
  return { page, size };
}

function dateOf(q: Record<string, unknown>, name: string, label: string): string {
  const value = text(q[name]);
  if (value === '') {
    throw invalid(label + '을(를) 입력하세요.');
  }
  if (!DATE_FORMAT.test(value)) {
    throw invalid(label + '은(는) YYYY-MM-DD 형식이어야 합니다.');
  }
  return value;
}

function idOf(value: unknown, label: string): string | null {
  const raw = text(value);
  if (raw === '') {
    return null;
  }
  if (!/^\d+$/.test(raw)) {
    throw invalid(label + '은(는) 숫자여야 합니다.');
  }
  return raw;
}

async function assertRange(db: Db, startDate: string, endDate: string): Promise<void> {
  const rows = await db.query(
    `SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "late"`,
    { startDate, endDate },
  );
  if (rows[0] && rows[0].late === true) {
    throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
  }
}

@Controller('api/v1')
export class FnSfr00906Controller {
  @Get('/loan-statements')
  async listLoanStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pageOf(q);
    const startDate = dateOf(q, 'startDate', '조회 시작일');
    const endDate = dateOf(q, 'endDate', '조회 종료일');
    const loanType = text(q['loanType']);
    if (!LOAN_TYPES.includes(loanType)) {
      throw invalid('구분은 BORROWING 또는 LENDING이어야 합니다.');
    }
    const partnerId = idOf(q['partnerId'], '거래처');
    return transaction(async (db) => {
      await assertRange(db, startDate, endDate);
      // 가정: 조회 기간은 차입금·대여금의 거래일(loan_date) 기준이다.
      const params = { startDate, endDate, loanType, partnerId };
      const totals = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM loan l
         WHERE l.loan_type = :loanType
           AND l.loan_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)
           AND (CAST(:partnerId AS bigint) IS NULL OR l.partner_id = CAST(:partnerId AS bigint))`,
        params,
      );
      // 가정: 상환 합계는 조회 기간 내 REPAYMENT 거래 금액의 합계, 잔액은 원금 - 상환 합계이다.
      const items = await db.query(
        `SELECT s."loanId", s."partnerId", s."principalAmount", s."voucherStatus", s."repaidAmount",
                s."principalAmount" - s."repaidAmount" AS "balance"
         FROM (
           SELECT l.loan_id AS "loanId",
                  l.partner_id AS "partnerId",
                  l.principal_amount AS "principalAmount",
                  l.voucher_status AS "voucherStatus",
                  COALESCE((
                    SELECT SUM(t.amount)
                    FROM loan_transaction t
                    WHERE t.loan_id = l.loan_id
                      AND t.transaction_type = 'REPAYMENT'
                      AND t.transaction_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)
                  ), 0) AS "repaidAmount"
           FROM loan l
           WHERE l.loan_type = :loanType
             AND l.loan_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)
             AND (CAST(:partnerId AS bigint) IS NULL OR l.partner_id = CAST(:partnerId AS bigint))
         ) s
         ORDER BY s."loanId" DESC
         OFFSET CAST(:offset AS int) LIMIT CAST(:limit AS int)`,
        { ...params, offset: page * size, limit: size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }

  @Post('/loans/:loanId/process-voucher')
  @HttpCode(200)
  async processLoanVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    checks.inputOf(req.body ?? {});
    const loanId = idOf(req.params['loanId'], '차입금·대여금 ID');
    if (loanId === null) {
      throw invalid('차입금·대여금 ID를 입력하세요.');
    }
    return transaction(async (db) => {
      const loans = await db.query(
        `SELECT loan_id AS "loanId", voucher_status AS "voucherStatus"
         FROM loan
         WHERE loan_id = CAST(:loanId AS bigint)
         FOR UPDATE`,
        { loanId },
      );
      if (loans.length === 0) {
        throw new ApiError(404, 'LOAN_NOT_FOUND', '대상 차입금·대여금을 찾을 수 없습니다.');
      }
      if (loans[0].voucherStatus !== '미처리') {
        throw new ApiError(409, 'LOAN_ALREADY_PROCESSED', '이미 전표처리된 건입니다.');
      }
      const mapped = await db.query(
        `SELECT l.loan_id AS "loanId"
         FROM loan l
         JOIN account_subject a ON a.account_subject_id = l.account_subject_id
         JOIN partner p ON p.partner_id = l.partner_id
         WHERE l.loan_id = CAST(:loanId AS bigint)`,
        { loanId },
      );
      if (mapped.length === 0) {
        throw new ApiError(422, 'VOUCHER_MAPPING_MISSING', '전표 생성에 필요한 계정과목·거래처가 없습니다.');
      }
      // 가정: 전표의 결의서는 같은 거래처의 가장 최근 승인 결의서로 정한다 (출처 미정, 개발 담당자 결정).
      const resolutions = await db.query(
        `SELECT er.expense_resolution_id AS "expenseResolutionId"
         FROM expense_resolution er
         JOIN loan l ON l.partner_id = er.partner_id
         WHERE l.loan_id = CAST(:loanId AS bigint)
           AND er.status = '승인'
         ORDER BY er.expense_resolution_id DESC
         LIMIT 1`,
        { loanId },
      );
      if (resolutions.length === 0) {
        throw new ApiError(422, 'VOUCHER_MAPPING_MISSING', '전표 생성에 필요한 결의서 기준정보가 없습니다.');
      }
      const resolutionId = String(resolutions[0].expenseResolutionId);
      // 가정: 전표 일자는 현재 일자, 상태는 '신청', 차대변 합계는 원금이다.
      const entries = await db.query(
        `INSERT INTO journal_entry
           (expense_resolution_id, entry_date, status, total_debit_amount, total_credit_amount, summary, created_at, updated_at)
         SELECT CAST(:resolutionId AS bigint), CAST(now() AS date), '신청',
                l.principal_amount, l.principal_amount, '차입금·대여금 전표처리', now(), now()
         FROM loan l
         WHERE l.loan_id = CAST(:loanId AS bigint)
         RETURNING journal_entry_id AS "journalEntryId"`,
        { resolutionId, loanId },
      );
      const journalEntryId = String(entries[0].journalEntryId);
      const linked = await db.execute(
        `UPDATE loan_transaction
         SET journal_entry_id = CAST(:journalEntryId AS bigint), updated_at = now()
         WHERE loan_id = CAST(:loanId AS bigint)
           AND transaction_type = 'OCCURRENCE'
           AND journal_entry_id IS NULL`,
        { journalEntryId, loanId },
      );
      if (linked === 0) {
        await db.execute(
          `INSERT INTO loan_transaction
             (loan_id, journal_entry_id, transaction_type, transaction_date, amount, balance_after, memo, created_at, updated_at)
           SELECT l.loan_id, CAST(:journalEntryId AS bigint), 'OCCURRENCE', l.loan_date,
                  l.principal_amount, l.principal_amount, '전표처리', now(), now()
           FROM loan l
           WHERE l.loan_id = CAST(:loanId AS bigint)`,
          { journalEntryId, loanId },
        );
      }
      const changed = await db.execute(
        `UPDATE loan
         SET voucher_status = '처리완료', updated_at = now()
         WHERE loan_id = CAST(:loanId AS bigint)
           AND voucher_status = '미처리'`,
        { loanId },
      );
      if (changed === 0) {
        throw new ApiError(409, 'LOAN_ALREADY_PROCESSED', '이미 전표처리된 건입니다.');
      }
      return { journalEntryId: Number(journalEntryId), voucherStatus: '처리완료' };
    });
  }

  @Get('/loan-transactions')
  async listLoanTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pageOf(q);
    const startDate = dateOf(q, 'startDate', '조회 시작일');
    const endDate = dateOf(q, 'endDate', '조회 종료일');
    const loanId = idOf(q['loanId'], '차입금·대여금');
    const partnerId = idOf(q['partnerId'], '거래처');
    const rawType = text(q['loanType']);
    if (rawType !== '' && !LOAN_TYPES.includes(rawType)) {
      throw invalid('구분은 BORROWING 또는 LENDING이어야 합니다.');
    }
    const loanType = rawType === '' ? null : rawType;
    return transaction(async (db) => {
      await assertRange(db, startDate, endDate);
      const params = { startDate, endDate, loanId, loanType, partnerId };
      const where = `
        WHERE t.transaction_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)
          AND (CAST(:loanId AS bigint) IS NULL OR t.loan_id = CAST(:loanId AS bigint))
          AND (CAST(:loanType AS varchar) IS NULL OR l.loan_type = CAST(:loanType AS varchar))
          AND (CAST(:partnerId AS bigint) IS NULL OR l.partner_id = CAST(:partnerId AS bigint))`;
      const totals = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM loan_transaction t
         JOIN loan l ON l.loan_id = t.loan_id` + where,
        params,
      );
      const items = await db.query(
        `SELECT t.loan_transaction_id AS "loanTransactionId",
                t.transaction_type AS "transactionType",
                t.transaction_date AS "transactionDate",
                t.amount AS "amount",
                t.balance_after AS "balanceAfter",
                t.memo AS "memo"
         FROM loan_transaction t
         JOIN loan l ON l.loan_id = t.loan_id` + where + `
         ORDER BY t.transaction_date, t.loan_transaction_id
         OFFSET CAST(:offset AS int) LIMIT CAST(:limit AS int)`,
        { ...params, offset: page * size, limit: size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }
}

