import { useState } from 'react';
import {
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  RefName,
  Select,
  Band,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;
const EMPTY: Page = { items: [], page: 0, size: PAGE_SIZE, total: 0 };
const LOAN_TYPE_LABEL: Record<string, string> = { BORROWING: '차입금', LENDING: '대여금' };
const TRANSACTION_LABEL: Record<string, string> = { OCCURRENCE: '발생', REPAYMENT: '상환', INTEREST: '이자' };

export default function FnSfr00906Page({ role, notify }: PageProps) {
  const [loanType, setLoanType] = useState('BORROWING');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [query, setQuery] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [ledgerPageNo, setLedgerPageNo] = useState(0);
  const [formError, setFormError] = useState('');
  const [target, setTarget] = useState<Row | null>(null);
  const [detail, setDetail] = useState<Row | null>(null);

  const statements = useData<Page>(async () => {
    if (!query) {
      return EMPTY;
    }
    return call<Page>('GET', '/loan-statements', role, undefined, { ...query, page: pageNo, size: PAGE_SIZE });
  }, [query, pageNo, role]);

  const ledger = useData<Page>(async () => {
    if (!query || !detail) {
      return EMPTY;
    }
    return call<Page>('GET', '/loan-transactions', role, undefined, {
      loanId: detail['loanId'],
      startDate: query['startDate'],
      endDate: query['endDate'],
      page: ledgerPageNo,
      size: PAGE_SIZE,
    });
  }, [query, detail, ledgerPageNo, role]);

  const search = () => {
    if (startDate === '' || endDate === '') {
      setFormError('조회 시작일과 종료일을 입력하세요.');
      return;
    }
    if (startDate > endDate) {
      setFormError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setQuery({ loanType, startDate, endDate, partnerId });
  };

  const reset = () => {
    setLoanType('BORROWING');
    setStartDate('');
    setEndDate('');
    setPartnerId('');
    setFormError('');
    setQuery(null);
    setPageNo(0);
  };

  const processVoucher = async () => {
    if (!target) {
      return;
    }
    await call('POST', '/loans/' + String(target['loanId']) + '/process-voucher', role, {});
    notify('전표처리를 했습니다.');
    setTarget(null);
    statements.reload();
  };

  if (detail) {
    return (
      <div className="doc">
        <button
          className="ghost"
          onClick={() => {
            setDetail(null);
            setLedgerPageNo(0);
          }}
        >
          명세서 목록으로 돌아가기
        </button>
        <section className="box">
          <h2>차입금·대여금 요약</h2>
          <Pairs
            items={[
              ['거래처', <RefName table="partner" role={role} value={detail['partnerId']} />],
              ['원금', <Num value={detail['principalAmount']} />],
              ['상환 합계', <Num value={detail['repaidAmount']} />],
              ['잔액', <Num value={detail['balance']} />],
              ['전표처리 상태', <Badge value={detail['voucherStatus']} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>차입금·대여금 원장</h2>
          {ledger.error ? <ErrorText text={ledger.error} /> : null}
          <Band total={ledger.data?.total} />
          <DataTable
            columns={[
              { key: 'transactionDate', label: '거래일', render: (row) => <DateText value={row['transactionDate']} /> },
              {
                key: 'transactionType',
                label: '거래 유형',
                render: (row) => TRANSACTION_LABEL[String(row['transactionType'])] ?? String(row['transactionType']),
              },
              { key: 'amount', label: '거래금액', render: (row) => <Num value={row['amount']} /> },
              { key: 'balanceAfter', label: '거래 후 잔액', render: (row) => <Num value={row['balanceAfter']} /> },
              { key: 'memo', label: '적요' },
            ]}
            rows={ledger.data?.items ?? []}
            empty="이 기간에는 원장 거래 내역이 없습니다. 기간을 넓혀 다시 조회해 보세요."
          />
          <Pager page={ledgerPageNo} size={PAGE_SIZE} total={ledger.data?.total ?? 0} onPage={setLedgerPageNo} />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>차입금·대여금 명세서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="구분" required>
            <Select
              value={loanType}
              onChange={setLoanType}
              options={[
                ['BORROWING', '차입금'],
                ['LENDING', '대여금'],
              ]}
            />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {statements.error ? <ErrorText text={statements.error} /> : null}
        <Band total={statements.data?.total} />
        <DataTable
          columns={[
            { key: 'partnerId', label: '거래처', render: (row) => <RefName table="partner" role={role} value={row['partnerId']} /> },
            { key: 'principalAmount', label: '원금', render: (row) => <Num value={row['principalAmount']} /> },
            { key: 'balance', label: '잔액', render: (row) => <Num value={row['balance']} /> },
            { key: 'voucherStatus', label: '전표처리 상태', render: (row) => <Badge value={row['voucherStatus']} /> },
            {
              key: 'actions',
              label: '작업',
              render: (row) => (
                <span>
                  <button
                    className="ghost"
                    onClick={() => {
                      setLedgerPageNo(0);
                      setDetail(row);
                    }}
                  >
                    원장 보기
                  </button>
                  {row['voucherStatus'] === '미처리' ? (
                    <button className="ghost" onClick={() => setTarget(row)}>
                      전표처리
                    </button>
                  ) : null}
                </span>
              ),
            },
          ]}
          rows={statements.data?.items ?? []}
          empty={query ? '조건에 맞는 명세서가 없습니다. 구분과 기간을 바꿔 다시 조회해 보세요.' : '구분과 기간을 정해 조회하면 명세서가 나타납니다.'}
        />
        <Pager page={pageNo} size={PAGE_SIZE} total={statements.data?.total ?? 0} onPage={setPageNo} />
      </section>
      {target ? (
        <Drawer title="차입금·대여금 전표처리" onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['거래처', <RefName table="partner" role={role} value={target['partnerId']} />],
              ['원금', <Num value={target['principalAmount']} />],
              ['전표처리 상태', <Badge value={target['voucherStatus']} />],
            ]}
          />
          <Form
            onSubmit={processVoucher}
            submit="전표처리"
            danger
            note="전표처리를 하면 전표가 생성되고 처리 상태가 '처리완료'로 바뀌며, 같은 건을 다시 전표처리할 수 없습니다."
          />
        </Drawer>
      ) : null}
    </div>
  );
}
